import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {auditCallback} from '../src/routes/orders.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';

test('routes registration order and count are preserved', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({method: r.method, path: r.path})),
    [
      {method: 'GET', path: '/accounts/:id'},
      {method: 'POST', path: '/accounts'},
      {method: 'GET', path: '/health'},
      {method: 'GET', path: '/orders/:id'},
      {method: 'DELETE', path: '/orders/:id'},
    ]
  );
});

test('synchronous health route is preserved and responds synchronously', () => {
  const router = makeRouter();
  const healthRoute = router.routes.find(r => r.path === '/health');
  assert.ok(healthRoute);
  let nextCalled = false;
  const res = {send: (val) => val};
  const result = healthRoute.handler({id: '1'}, res, (err) => { nextCalled = true; });
  assert.equal(result, 'ok');
  assert.equal(nextCalled, false);
});

test('GET /accounts/:id succeeds and forwards errors to next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
  assert.ok(route);

  // Success
  let errors = [];
  const next = (err) => errors.push(err);
  const successRes = {send: (val) => `sent:${val}`};
  const result = await route.handler({id: 'acc1'}, successRes, next);
  assert.equal(result, 'sent:account:acc1');
  assert.equal(errors.length, 0);

  // Failure forwarded to next
  await route.handler({id: 'acc1', fail: true}, successRes, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0].message, 'account read');
});

test('POST /accounts succeeds and forwards errors to next (named async function)', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
  assert.ok(route);

  // Success
  let errors = [];
  const next = (err) => errors.push(err);
  const successRes = {send: (val) => `sent:${val}`};
  const result = await route.handler({id: 'acc2'}, successRes, next);
  assert.equal(result, 'sent:created:acc2');
  assert.equal(errors.length, 0);

  // Failure forwarded to next
  await route.handler({id: 'acc2', fail: true}, successRes, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0].message, 'account create');
});

test('GET /orders/:id succeeds and forwards errors to next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
  assert.ok(route);

  // Success
  let errors = [];
  const next = (err) => errors.push(err);
  const successRes = {send: (val) => `sent:${val}`};
  const result = await route.handler({id: 'ord1'}, successRes, next);
  assert.equal(result, 'sent:ORD1');
  assert.equal(errors.length, 0);

  // Failure forwarded to next
  await route.handler({id: 'ord1', fail: true}, successRes, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0].message, 'order read');
});

test('DELETE /orders/:id succeeds and forwards errors to next', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
  assert.ok(route);

  // Success
  let errors = [];
  const next = (err) => errors.push(err);
  const successRes = {send: (val) => `sent:${val}`};
  const result = await route.handler({id: 'ord2'}, successRes, next);
  assert.equal(result, 'sent:deleted:ord2');
  assert.equal(errors.length, 0);

  // Failure forwarded to next
  await route.handler({id: 'ord2', fail: true}, successRes, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0].message, 'order delete');
});

test('unrelated helpers and callbacks are unchanged', async () => {
  await assert.rejects(async () => {
    await unrelatedHelper();
  }, {message: 'helper'});

  await assert.rejects(async () => {
    await auditCallback();
  }, {message: 'audit'});
});

